<script setup lang="ts">
import { copyText } from './clipboard'
import { ref, reactive } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, type Node, type NodeInput, type NodeGroup } from './api'
import Icon from './Icon.vue'
import LimitInput from './LimitInput.vue'
import {nodeTLSDefaults as tlsDefaults,nodeBasicInput} from './node-protocol'
withDefaults(defineProps<{ nodes: Node[]; groups: NodeGroup[]; view?: 'nodes' | 'groups' }>(), {view:'nodes'})
const emit = defineEmits<{ refresh: [] }>()
const latestVersion=ref(''),checkingUpdate=ref(false),updatingNode=ref(0)
async function checkUpdates(){checkingUpdate.value=true;try{const data=await api<{latest:{version:string}}>('admin/updates');latestVersion.value=data.latest.version;ElMessage.success(`最新版本：${latestVersion.value}`)}catch(e){ElMessage.error((e as Error).message)}finally{checkingUpdate.value=false}}
async function updateNode(n:Node){if(!n.update_supported){ElMessage.warning('请先重新运行新版节点安装命令，以安装更新服务');return}if(!latestVersion.value)await checkUpdates();if(!latestVersion.value)return;try{await ElMessageBox.confirm(`更新到 ${latestVersion.value} 将重启节点并中断现有转发连接。`,'更新节点',{confirmButtonText:'更新',cancelButtonText:'取消'});updatingNode.value=n.id;await api(`admin/nodes/${n.id}/update`,'POST',{version:latestVersion.value});ElMessage.success('更新任务已下发');emit('refresh')}catch(e){if(e instanceof Error)ElMessage.error(e.message)}finally{updatingNode.value=0}}
const updateStates:Record<string,string>={queued:'等待更新',running:'更新中',completed:'已更新',failed:'更新失败',unconfirmed:'更新结果未确认'}
const nodeDialog = ref(false), groupDialog = ref(false), editID = ref(0), groupID = ref(0), busy = ref(false), interfaces = ref('')
const installDialog = ref(false), installCommand = ref(''), installExisting = ref(false)
async function installation(id: number) { await act(async () => { const data = await api<{command: string; existing_node: boolean}>(`admin/nodes/${id}/install-command`, 'POST', {}); installCommand.value = data.command; installExisting.value = data.existing_node; installDialog.value = true }) }
async function copyInstall() { try { await copyText(installCommand.value); ElMessage.success('安装命令已复制') } catch { ElMessage.warning('复制失败，请手动选择复制') } }
async function copyToken(value:string) { try { await copyText(value);ElMessage.success('节点密钥已复制') } catch { ElMessage.warning('复制失败，请手动选择复制') } }
const originalToken=ref('')
const defaults = (): NodeInput => ({tls:tlsDefaults(), token:'', ingress_enabled:true, allow_direct:true, tunnel_exit_enabled:false, tunnel_protocol:'plain_tcp', tunnel_listen_host:'0.0.0.0', tunnel_listen_port:0, tunnel_public_host:'', allowed_ingress_ids:[], name: '', public_address: '', notes: '', enabled: true, group_ids: [], listen_host: '0.0.0.0', port_min: 1024, port_max: 65535, max_connections: 10000, dial_timeout_seconds: 8, idle_timeout_seconds: 300, probe_interval_seconds: 5, disk_path: '/', network_interfaces: [] })
const nodeForm = reactive(defaults()), groupForm = reactive({ name: '', description: '', enabled: true, sort_order: 0, node_ids: [] as number[] })
function editNode(n?: Node) { editID.value = n?.id || 0; for (const k of Object.keys(defaults()) as (keyof NodeInput)[]) (nodeForm as any)[k] = n ? n[k] : defaults()[k]; nodeForm.tls={...tlsDefaults(),...(nodeForm.tls||{})};nodeForm.group_ids = [...nodeForm.group_ids]; nodeForm.allowed_ingress_ids=[...(nodeForm.allowed_ingress_ids||[])]; nodeForm.network_interfaces = [...nodeForm.network_interfaces]; interfaces.value = nodeForm.network_interfaces.join('\n'); originalToken.value=nodeForm.token;nodeDialog.value = true }
function editGroup(g?: NodeGroup) { groupID.value = g?.id || 0; Object.assign(groupForm, { name: g?.name || '', description: g?.description || '', enabled: g?.enabled ?? true, sort_order: g?.sort_order || 0, node_ids: [...(g?.node_ids || [])] }); groupDialog.value = true }
async function act(f: () => Promise<void>) { busy.value = true; try { await f(); emit('refresh') } catch (e) { ElMessage.error((e as Error).message) } finally { busy.value = false } }
async function saveNode() { await act(async()=>{
 nodeForm.network_interfaces=interfaces.value.split(/[,\s]+/).filter(Boolean)
 const creating=!editID.value
 const data=await api<{id:number;token:string}>(creating?'admin/nodes':`admin/nodes/${editID.value}/basic`,creating?'POST':'PUT',creating?nodeForm:nodeBasicInput(nodeForm,originalToken.value))
 editID.value=data.id;nodeForm.token=data.token;originalToken.value=data.token;ElMessage.success(creating?'节点已创建，密钥已填入下方':'节点配置已保存，密钥可在下方复制')
}) }

async function saveGroup() { await act(async () => { await api(`admin/node-groups${groupID.value ? '/' + groupID.value : ''}`, groupID.value ? 'PUT' : 'POST', groupForm); groupDialog.value = false; ElMessage.success('节点组已保存') }) }
async function remove(kind: 'nodes' | 'node-groups', id: number) { try { await ElMessageBox.confirm(kind === 'nodes' ? '删除节点？存在规则或历史账本的节点应使用停用。' : '删除节点组？正在被套餐使用的组无法删除。', '确认删除', { confirmButtonText: '删除', cancelButtonText: '取消' }); await act(async () => { await api(`admin/${kind}/${id}`, 'DELETE', {}) }) } catch { /* cancelled */ } }
</script>
<template>
 <section class="surface"><div class="section-header"><strong>{{view === 'groups' ? '节点组管理' : '节点管理'}}</strong><div class="admin-actions"><el-button :loading="checkingUpdate" @click="checkUpdates">检查更新{{latestVersion ? ` · ${latestVersion}` : ''}}</el-button><el-button @click="editGroup()"><Icon name="folder" />创建节点组</el-button><el-button type="primary" @click="editNode()"><Icon name="add" />添加节点</el-button></div></div><div class="section-body"><nav class="admin-resource-tabs"><a href="/admin/nodes" :class="{active:view==='nodes'}">节点列表</a><a href="/admin/node_groups" :class="{active:view==='groups'}">节点组</a></nav><div v-if="view==='nodes'"><p class="subtle management-intro">入口与出口关系、隧道端口、转发限制和探针配置均由主控下发。节点只需配置主控连接信息。</p><el-table :data="nodes" empty-text="暂无节点"><el-table-column prop="name" label="名称" min-width="150" /><el-table-column prop="public_address" label="公网地址" min-width="170"><template #default="{ row }">{{ row.public_address || '未配置' }}</template></el-table-column><el-table-column label="节点组" min-width="200"><template #default="{ row }"><span v-if="!row.group_ids.length" class="subtle">未分组</span><el-tag v-for="id in row.group_ids" :key="id" class="group-chip">{{ groups.find(g => g.id === id)?.name || id }}</el-tag></template></el-table-column><el-table-column label="用途" width="130"><template #default="{ row }"><el-tag v-if="row.ingress_enabled" class="group-chip">入口</el-tag><el-tag v-if="row.tunnel_exit_enabled" class="group-chip" type="success">出口</el-tag><span v-if="!row.ingress_enabled && !row.tunnel_exit_enabled" class="subtle">未启用</span></template></el-table-column><el-table-column label="状态" width="100"><template #default="{ row }">{{ !row.enabled ? '已停用' : row.online ? '在线' : '离线' }}</template></el-table-column><el-table-column label="配置同步" min-width="180"><template #default="{ row }"><span :class="{ danger: row.sync_error }">{{ row.sync_error || (row.applied_revision >= row.config_revision && row.applied_revision ? '已同步' : '等待同步') }}</span></template></el-table-column><el-table-column label="节点版本" min-width="170"><template #default="{row}"><div>{{row.agent_version || '未知版本'}}</div><small v-if="row.update_status" :class="{danger:row.update_status.state==='failed'}">{{updateStates[row.update_status.state]}} {{row.update_status.error}}</small><small v-else-if="!row.update_supported" class="subtle">需安装更新服务</small></template></el-table-column><el-table-column label="TLS 证书" min-width="170"><template #default="{row}"><span v-if="row.tunnel_protocol==='tls_h2'">{{row.tls_error || row.tls_status}}<small v-if="row.tls_not_after"> · {{new Date(row.tls_not_after).toLocaleDateString()}}</small></span><span v-else>—</span></template></el-table-column><el-table-column prop="active_connections" label="转发连接" width="100" /><el-table-column label="操作" width="400"><template #default="{ row }"><el-button link type="primary" @click="installation(row.id)">安装命令</el-button><el-button link type="primary" @click="editNode(row)">编辑</el-button><el-button link type="primary" tag="a" :href="`/admin/nodes/${row.id}/protocols`">传输协议</el-button><el-button link type="primary" tag="a" :href="`/admin/nodes/${row.id}/ddns`">DDNS</el-button><el-button link type="primary" :loading="updatingNode===row.id" :disabled="!row.online || ['queued','running'].includes(row.update_status?.state || '')" @click="updateNode(row)">更新</el-button><el-button link type="danger" @click="remove('nodes', row.id)">删除</el-button></template></el-table-column></el-table></div><div v-else><el-table :data="groups" empty-text="暂无节点组"><el-table-column prop="name" label="名称" min-width="170" /><el-table-column prop="description" label="说明" min-width="200" /><el-table-column label="节点数" width="100"><template #default="{ row }">{{ row.node_ids.length }}</template></el-table-column><el-table-column prop="plan_count" label="关联套餐" width="100" /><el-table-column prop="sort_order" label="显示顺序" width="100" /><el-table-column label="状态" width="100"><template #default="{ row }">{{ row.enabled ? '启用' : '停用' }}</template></el-table-column><el-table-column label="操作" width="130"><template #default="{ row }"><el-button link type="primary" @click="editGroup(row)">编辑</el-button><el-button link type="danger" :disabled="row.plan_count > 0" @click="remove('node-groups', row.id)">删除</el-button></template></el-table-column></el-table></div></div></section>
 <el-dialog v-model="nodeDialog" :title="editID ? '编辑节点' : '添加节点'" width="700px" top="4vh" class="managed-form-dialog"><el-form label-position="top"><div class="form-grid"><el-form-item label="节点名称"><el-input v-model="nodeForm.name" maxlength="80" /></el-form-item><el-form-item label="公网 IP / 域名"><el-input v-model="nodeForm.public_address" placeholder="用于转发入口地址" /></el-form-item></div><el-form-item label="节点密钥"><el-input v-model="nodeForm.token" placeholder="留空保存后自动生成"><template #append><el-button :disabled="!nodeForm.token" @click="copyToken(nodeForm.token)">复制</el-button></template></el-input><span class="field-tip">留空保存会生成新密钥；修改已安装节点的密钥后，还需更新节点端的 NEKOPASS_NODE_TOKEN 并重启服务。</span></el-form-item><el-form-item label="备注（仅管理员可见）"><el-input v-model="nodeForm.notes" type="textarea" :rows="2" /></el-form-item><el-form-item label="所属节点组"><el-select v-model="nodeForm.group_ids" multiple filterable><el-option v-for="g in groups" :key="g.id" :label="g.name" :value="g.id" /></el-select></el-form-item><div class="form-section-title">转发设置</div><div class="form-grid"><el-form-item label="监听地址"><el-input v-model="nodeForm.listen_host" placeholder="0.0.0.0 或 ::" /></el-form-item><el-form-item label="节点总连接数上限"><LimitInput v-model="nodeForm.max_connections" unit="条" :max="1000000" /></el-form-item><el-form-item label="可分配端口起始"><el-input-number v-model="nodeForm.port_min" :min="1024" :max="65535" /></el-form-item><el-form-item label="可分配端口结束"><el-input-number v-model="nodeForm.port_max" :min="nodeForm.port_min" :max="65535" /></el-form-item><el-form-item label="目标建连超时 / 秒"><el-input-number v-model="nodeForm.dial_timeout_seconds" :min="1" :max="120" /></el-form-item><el-form-item label="空闲连接超时 / 秒"><el-input-number v-model="nodeForm.idle_timeout_seconds" :min="10" :max="86400" /></el-form-item></div><div class="form-section-title">入口与出口</div><div class="admin-actions"><el-tag :type="nodeForm.ingress_enabled?'success':'info'">入口 {{nodeForm.ingress_enabled?'已启用':'未启用'}}</el-tag><el-tag :type="nodeForm.tunnel_exit_enabled?'success':'info'">出口 {{nodeForm.tunnel_exit_enabled?'已启用':'未启用'}}</el-tag><el-button v-if="editID" tag="a" :href="`/admin/nodes/${editID}/protocols`" type="primary" plain>配置入口、出口与传输协议</el-button></div><p v-if="!editID" class="field-tip">保存节点后可进入传输协议页面配置入口和出口。</p><div class="form-section-title">探针设置</div><div class="form-grid"><el-form-item label="采样间隔 / 秒"><el-input-number v-model="nodeForm.probe_interval_seconds" :min="2" :max="60" /></el-form-item><el-form-item label="磁盘监测路径"><el-input v-model="nodeForm.disk_path" placeholder="/" /></el-form-item></div><el-form-item label="统计网卡"><el-input v-model="interfaces" type="textarea" :rows="2" placeholder="留空自动选择默认路由网卡；手动填写时一行一个，如 eth0" /></el-form-item><el-form-item label="启用节点"><el-switch v-model="nodeForm.enabled" /><span class="field-tip switch-hint">停用会关闭该节点上的转发，保留主控连接和探针上报。</span></el-form-item></el-form><template #footer><el-button @click="nodeDialog = false">关闭</el-button><el-button type="primary" :loading="busy" @click="saveNode">保存并下发</el-button></template></el-dialog>
 <el-dialog v-model="groupDialog" :title="groupID ? '编辑节点组' : '创建节点组'" width="550px"><el-form label-position="top"><el-form-item label="节点组名称"><el-input v-model="groupForm.name" /></el-form-item><el-form-item label="说明"><el-input v-model="groupForm.description" type="textarea" :rows="2" /></el-form-item><el-form-item label="组内节点"><el-select v-model="groupForm.node_ids" multiple filterable><el-option v-for="n in nodes" :key="n.id" :label="n.name" :value="n.id" /></el-select></el-form-item><el-form-item label="显示顺序"><el-input-number v-model="groupForm.sort_order" /></el-form-item><el-form-item label="启用节点组"><el-switch v-model="groupForm.enabled" /></el-form-item></el-form><template #footer><el-button @click="groupDialog = false">取消</el-button><el-button type="primary" :loading="busy" @click="saveGroup">保存节点组</el-button></template></el-dialog>
 
<el-dialog v-model="installDialog" title="节点一键安装命令" width="780px" @closed="installCommand=''">
 <p>在节点服务器上以 root 运行。命令已包含面板地址、主控端口、此节点密钥和连接方式。</p>
 <p v-if="installExisting" class="field-tip">此节点已绑定服务器，命令仅用于原机器升级，会验证并保留原密钥与状态文件。新服务器请新建节点。</p>
 <p v-else class="field-tip">wget 下载脚本后由 bash 执行；命令可重复使用，更换节点密钥后重新复制。</p>
 <el-input :model-value="installCommand" type="textarea" :rows="6" readonly class="install-command" />
 <p class="field-tip">下载源、版本、主控地址和连接方式来自 <a class="text-link" href="/admin/settings">系统设置</a>。管理 API 密钥不会下发到节点。</p>
 <template #footer><el-button @click="installDialog=false">关闭</el-button><el-button type="primary" @click="copyInstall">复制安装命令</el-button></template>
 </el-dialog>
</template>
